func solve(health: int, damage: int) -> void:
	print_health(health)
	print_damage(damage)
	print_remaining(health, damage)

func print_health(health: int) -> void:
	print(health)

func print_damage(damage: int) -> void:
	print(damage)

func print_remaining(health: int, damage: int) -> void:
	print(health - damage)
